 for(const e of enemies){
   if(e.dead) continue;
   const dx=player.x-e.x, dz=player.z-e.z, dist=Math.hypot(dx,dz)||.001;
   const nx=dx/dist, nz=dz/dist;
   const dotBeam = fwd.x*nx+fwd.z*nz;
