function addItem(type,label){if(inventory.length>=5){toast('Inventario lleno. Deja algo atrás.');return false;}inventory.push({type,label});updateUI();return true;}
function updateUI(){const p=player;for(const [id,value] of [['health',p.hp],['food',p.food],['water',p.water],['infection',p.inf]]){$(id+'Bar').style.width=Math.max(0,Math.min(100,value))+'%';$(id+'Num').textContent=Math.round(value);}const list=$('inventory');list.innerHTML='';for(let i=0;i<5;i++){const s=document.createElement('div');s.className='slot'+(i===selected?' selected':'')+(inventory[i]?'':' empty');if(inventory[i]){const data=itemNames[inventory[i].type]||['?','?'];s.innerHTML=data[0]+'<small>'+data[1]+'</small>';s.title=inventory[i].label;s.onclick=()=>{selected=i;updateUI();};}else s.textContent='·';list.appendChild(s);}const hasKey=inventory.some(i=>i.type==='key');$('doorState').textContent=roomIndex===4?'SALIDA ABIERTA':hasKey?'LLAVE ENCONTRADA':'PUERTA CERRADA';$('weapon').textContent=(p.gun?'PISTOLA':'SIN ARMA')+(p.gun?' · '+p.ammo+' BALAS':'');$('objective').innerHTML=roomIndex===4?'Llega a la puerta norte y escapa del hotel.':hasKey?`La salida está abierta. <b>Encuentra la puerta norte.</b>`:`Busca ${rooms[roomIndex].key}. La puerta está al norte.`;}
function targetInteractable(){const forward=v3(-Math.sin(player.yaw),0,-Math.cos(player.yaw));let best=null,bestDist=3;for(const item of interactables){if(item.type==='item'&&item.collected)continue;const d=item.position.distanceTo(v3(player.x,0,player.z)),to=item.position.clone().sub(v3(player.x,0,player.z)).normalize();if(d<bestDist&&(d<1.6||to.dot(forward)>.72)){best=item;bestDist=d;}}return best;}
function interact(target){if(!target)return;if(target.type==='item'){if(target.itemType==='key'&&roomIndex<4&&inventory.length>=5){toast('Inventario lleno. Deja un objeto atrás.');return;}if(!addItem(target.itemType,target.label))return;target.collected=true;target.object.visible=false;if(target.itemType==='key')toast('Llave encontrada. La puerta norte se ha abierto.');else if(target.itemType==='ammo'){player.ammo=(player.ammo||0)+4;const i=inventory.findIndex(x=>x.type==='ammo');if(i>=0)inventory.splice(i,1);toast('Cuatro balas.');}else if(target.itemType==='gun'){player.gun=true;toast('Pistola vieja: clic para disparar.');}else toast(target.label+' recogido.');updateUI();return;}if(target.type==='hide'){hidden=!hidden;$('hideNote').classList.toggle('show',hidden);toast(hidden?'Te escondes entre las sombras.':'Sales del escondite.');return;}if(target.type==='exit'){const keyIndex=inventory.findIndex(i=>i.type==='key');if(roomIndex<4&&keyIndex<0){toast('Cerrada. La llave debe estar en esta planta.');return;}if(keyIndex>=0)inventory.splice(keyIndex,1);if(roomIndex===4){finish(true);return;}$('fade').classList.add('show');setTimeout(()=>{$('fade').classList.remove('show');roomIndex++;player.x=0;player.z=4.8;buildRoom();toast(rooms[roomIndex].name+'. No te detengas.');},420);}}
function useItem(){const item=inventory[selected];if(!item){toast('Selecciona un objeto del inventario.');return;}if(item.type==='food'){player.food=Math.min(100,player.food+38);inventory.splice(selected,1);toast('Comes deprisa.');}else if(item.type==='water'){player.water=Math.min(100,player.water+42);inventory.splice(selected,1);toast('Un trago de agua.');}else if(item.type==='vaccine'){player.inf=Math.max(0,player.inf-55);player.hp=Math.min(100,player.hp+12);inventory.splice(selected,1);toast('La vacuna frena la infección.');}else{toast('No puedes usar eso ahora.');return;}selected=Math.max(0,Math.min(selected,inventory.length-1));updateUI();}
function finish(win){ended=true;gameOn=false;document.exitPointerLock?.();$('endTitle').textContent=win?'AMANECE EN EL PISO 13':'EL HOTEL TE RETIENE';$('endText').textContent=win?'Las puertas del montacargas se cierran. Al otro lado, por primera vez, no hay pasos. Has escapado.':'La oscuridad del hotel te cubre. Las puertas siguen ahí; quizá esta vez encuentres la llave.';$('ending').classList.remove('hidden');}
function restart(){roomIndex=0;player={x:0,z:4.7,yaw:0,pitch:0,hp:100,food:100,water:100,inf:0,ammo:0,gun:false};inventory=[];selected=0;flashlight=true;hidden=false;gameOn=true;ended=false;$('intro').classList.add('hidden');$('ending').classList.add('hidden');$('hideNote').classList.remove('show');buildRoom();toast('Encuentra la llave del ala este.');}
function start(){if(gameOn)return;restart();if(matchMedia('(pointer:fine)').matches)canvas.requestPointerLock?.();}
function getForward(){return v3(-Math.sin(player.yaw)*Math.cos(player.pitch),Math.sin(player.pitch),-Math.cos(player.yaw)*Math.cos(player.pitch));}
function shoot(){if(!gameOn||!player.gun||player.ammo<=0||performance.now()-lastShot<450)return;lastShot=performance.now();player.ammo--;updateUI();raycaster.setFromCamera(new T.Vector2(0,0),camera);if(enemy?.alive){const to=v3(enemy.x-player.x,1.1,enemy.z-player.z),dir=getForward();if(to.length()<12&&dir.dot(to.normalize())>.96){enemy.hp--;enemy.stun=1.6;toast(enemy.hp<=0?'La criatura cae, pero el hotel sigue vivo.':'El disparo retumba en el pasillo.');if(enemy.hp<=0){enemy.alive=false;enemy.group.visible=false;}}}else toast('El disparo retumba por el hotel.');}
function canMove(x,z){if(x<-6.35||x>6.35||z<-6.35||z>6.35)return false;for(const o of obstacles){if(o.door&&inventory.some(i=>i.type==='key'))continue;if(Math.hypot(x-o.x,z-o.z)<o.r+.24)return false;}return true;}
function tick(dt){if(!gameOn)return;const forward=(held.KeyW||held.ArrowUp?1:0)-(held.KeyS||held.ArrowDown?1:0)-joy.y;const strafe=(held.KeyD||held.ArrowRight?1:0)-(held.KeyA||held.ArrowLeft?1:0)+joy.x;let dx=-Math.sin(player.yaw)*forward+Math.cos(player.yaw)*strafe,dz=-Math.cos(player.yaw)*forward-Math.sin(player.yaw)*strafe;const mag=Math.hypot(dx,dz);if(mag>1){dx/=mag;dz/=mag;}const moving=mag>.08,speed=(running?4.7:2.65)*(crouching?.55:1)*(hidden?0:1);if(moving){const nx=player.x+dx*speed*dt,nz=player.z+dz*speed*dt;if(canMove(nx,player.z))player.x=nx;if(canMove(player.x,nz))player.z=nz;}
 player.food=Math.max(0,player.food-dt*.17);player.water=Math.max(0,player.water-dt*.24);if(player.food<8||player.water<8)player.hp-=dt*.9;if(player.inf>0){player.inf=Math.max(0,player.inf-dt*.025);player.hp-=dt*player.inf*.0012;}camera.position.set(player.x,crouching?1.12:1.62,player.z);camera.rotation.set(player.pitch,player.yaw,0,'YXZ');lamp.visible=flashlight;lamp.intensity=flashlight?48:0;
 if(enemy?.alive){enemy.phase+=dt;enemy.stun=Math.max(0,enemy.stun-dt);const ex=player.x-enemy.x,ez=player.z-enemy.z,dist=Math.hypot(ex,ez);if(dist>.9&&!hidden&&enemy.stun<=0){const speedEnemy=roomIndex===1?1.05:.75;enemy.x+=ex/dist*speedEnemy*dt;enemy.z+=ez/dist*speedEnemy*dt;}enemy.group.position.set(enemy.x,Math.sin(enemy.phase*5)*.045,enemy.z);enemy.group.rotation.y=Math.atan2(player.x-enemy.x,player.z-enemy.z);if(dist<1.2&&!hidden&&enemy.stun<=0){player.hp-=dt*18;document.getElementById('danger').style.opacity='.8';}else document.getElementById('danger').style.opacity=Math.max(0,parseFloat(document.getElementById('danger').style.opacity||'0')-dt*1.8);}
 if(player.hp<=0){player.hp=0;updateUI();finish(false);return;}
 if(face){faceTime-=dt;face.material?.; if(faceTime<=0)face.visible=false;}faceCooldown-=dt;if(faceCooldown<=0&&flashlight&&Math.random()<dt*.24){raycaster.set(camera.position,getForward());raycaster.far=10;const hits=raycaster.intersectObjects(roomObjects,true).filter(h=>/wall|portrait/i.test(h.object.name));if(hits.length){const hit=hits[0],normal=hit.face.normal.clone().transformDirection(hit.object.matrixWorld);if(!face)face=makeFace();face.position.copy(hit.point).addScaledVector(normal,.025);face.quaternion.setFromUnitVectors(v3(0,0,1),normal);face.visible=true;faceTime=1.65;faceCooldown=8+Math.random()*8;toast('Algo te mira desde la pared…');}}
 const aim=targetInteractable(),prompt=$('prompt'),cross=$('crosshair');if(aim){prompt.innerHTML='<b>E</b>'+(aim.type==='item'?'RECOGER · '+aim.label.toUpperCase():aim.type==='hide'?(hidden?'SALIR DEL ESCONDITE':'ESCONDERSE'):'ABRIR / INTERACTUAR');prompt.classList.add('show');cross.classList.add('hot');}else{prompt.classList.remove('show');cross.classList.remove('hot');}
 if(performance.now()-uiTimer>600){updateUI();uiTimer=performance.now();}if(moving&&performance.now()-lastFoot>440){lastFoot=performance.now();if(audioOn)tone(62,.025,.018);}
}

