56: function makePickup(type,x,z,label){const group=new T.Group();group.position.set(x,.35,z);scene.add(group);roomObjects.push(group);const color=type==='key'?0xd9b65f:type==='food'?0x977546:type==='water'?0x6da4b1:type==='vaccine'?0x82bd79:type==='gun'?0x57534c:0xb34b3b;const gem=new T.Mesh(new T.OctahedronGeometry(.23,0),mat('item'+type,color,.25,color,.55));group.add(gem);const glow=new T.PointLight(color,1.1,2.6,2);glow.position.y=.2;group.add(glow);interactables.push({type:'item',itemType:type,label,position:v3(x,0,z),object:group});}
