58: function makeFace(){const c=document.createElement('canvas');c.width=256;c.height=256;const x=c.getContext('2d');x.clearRect(0,0,256,256);const grad=x.createRadialGradient(128,128,12,128,128,122);grad.addColorStop(0,'rgba(226,211,183,.95)');grad.addColorStop(.55,'rgba(144,127,111,.8)');grad.addColorStop(1,'rgba(35,25,22,0)');x.fillStyle=grad;x.fillRect(0,0,256,256);x.fillStyle='#100d0c';x.beginPath();x.ellipse(82,104,22,33,-.2,0,Math.PI*2);x.ellipse(174,104,22,33,.2,0,Math.PI*2);x.fill();x.fillStyle='#bb2c20';x.beginPath();x.arc(82,107,7,0,7);x.arc(174,107,7,0,7);x.fill();x.strokeStyle='#211412';x.lineWidth=12;x.beginPath();x.ellipse(128,174,35,22,0,0,Math.PI*2);x.stroke();x.fillStyle='#eee0cd';for(let i=0;i<7;i++)x.fillRect(101+i*9,164,5,17);const texture=new T.CanvasTexture(c);texture.colorSpace=T.SRGBColorSpace;const g=new T.Group(),mesh=new T.Mesh(new T.PlaneGeometry(1.7,1.7),new T.MeshBasicMaterial({map:texture,transparent:true,opacity:.93,depthWrite:false,side:T.DoubleSide}));g.add(mesh);g.visible=false;scene.add(g);roomObjects.push(g);return g;}
