404:   function interactWith(target) {
405:     if (!target) return;
406: 
407:     if (target.type === 'item') {
408:       if (!addInventory(target.itemType, target.label)) return;
409:       target.collected = true;
410:       target.object.visible = false;
411:       if (target.itemType === 'ammo') {
412:         state.player.ammo += 4;
413:         state.inventory = state.inventory.filter((it) => it.type !== 'ammo');
414:         toast('Recoges 4 balas.');
415:       } else if (target.itemType === 'gun') {
416:         state.player.gun = true;
417:         state.player.ammo = Math.max(state.player.ammo, 6);
418:         toast('Pistola recuperada.');
419:       } else if (target.itemType === 'key') {
420:         toast('Llave encontrada. La puerta del norte ya tiene sentido.');
421:       } else {
422:         toast(target.label + ' recogido.');
423:       }
424:       updateUI();
425:       return;
426:     }
427: 
428:     if (target.type === 'hide') {
429:       state.hidden = !state.hidden;
430:       $('hideNote').classList.toggle('show', state.hidden);
431:       toast(state.hidden ? 'Te escondes en la sombra.' : 'Sales del escondite.');
432:       return;
433:     }
434: 
435:     if (target.type === 'exit') {
436:       const keyIndex = state.inventory.findIndex((i) => i.type === 'key');
437:       if (state.roomIndex < 4 && keyIndex < 0) {
438:         toast('La puerta está cerrada; falta una llave.');
439:         return;
440:       }
441:       if (keyIndex >= 0) state.inventory.splice(keyIndex, 1);
442:       if (state.roomIndex === 4) {
443:         finish(true);
444:         return;
445:       }
446:       $('fade').classList.add('show');
447:       setTimeout(() => {
448:         $('fade').classList.remove('show');
449:         state.roomIndex += 1;
450:         state.player.x = 0;
451:         state.player.z = 4.7;
452:         state.player.yaw = 0;
453:         createRoom();
454:         toast(rooms[state.roomIndex].name + '. No te detengas.');
