504:   function createFace() {
505:     const g = new T.Group();
506:     const c = document.createElement('canvas');
507:     c.width = 256; c.height = 256;
508:     const ctx = c.getContext('2d');
509:     ctx.clearRect(0, 0, 256, 256);
510:     const grad = ctx.createRadialGradient(128, 128, 12, 128, 128, 128);
511:     grad.addColorStop(0, 'rgba(240,220,200,0.97)');
512:     grad.addColorStop(0.5, 'rgba(160,140,125,0.85)');
513:     grad.addColorStop(1, 'rgba(18,14,12,0)');
514:     ctx.fillStyle = grad;
515:     ctx.fillRect(0, 0, 256, 256);
516:     ctx.fillStyle = '#0d0c0c';
517:     ctx.beginPath(); ctx.ellipse(82, 104, 24, 32, -0.25, 0, Math.PI * 2); ctx.ellipse(174, 104, 24, 32, 0.25, 0, Math.PI * 2); ctx.fill();
518:     ctx.fillStyle = '#d53725';
519:     ctx.beginPath(); ctx.arc(82, 108, 8, 0, Math.PI * 2); ctx.arc(174, 108, 8, 0, Math.PI * 2); ctx.fill();
520:     ctx.strokeStyle = '#1c1211';
521:     ctx.lineWidth = 12;
522:     ctx.beginPath(); ctx.ellipse(128, 176, 40, 20, 0, 0, Math.PI * 2); ctx.stroke();
523:     const tex = new T.CanvasTexture(c);
524:     tex.colorSpace = T.SRGBColorSpace;
525:     const material = new T.MeshBasicMaterial({ map: tex, transparent: true, opacity: 0.94, side: T.DoubleSide, depthWrite: false });
526:     const mesh = new T.Mesh(new T.PlaneGeometry(1.8, 1.8), material);
527:     mesh.visible = false;
528:     g.add(mesh);
529:     scene.add(g);
530:     state.roomObj.push(g);
531:     state.face = g;
532:     return g;
533:   }
