535:   function maybeFaces() {
536:     if (!state.gameOn || !state.flashlight) return;
537:     state.faceCooldown -= 1 / 60;
538:     if (state.faceCooldown > 0) return;
539:     const dir = new T.Vector3(-Math.sin(state.player.yaw), Math.sin(state.player.pitch), -Math.cos(state.player.yaw)).normalize();
540:     raycaster.set(camera.position, dir);
541:     raycaster.far = 10;
542:     const hits = raycaster.intersectObjects(state.roomObj, true);
543:     const wallHit = hits.find((h) => /wall|portrait|door|floor|cabinet|wardrobe|table/i.test(h.object.name) || h.object.isMesh);
544:     if (!wallHit) return;
545:     const point = wallHit.point.clone();
546:     if (!state.face) createFace();
547:     state.face.visible = true;
548:     state.face.position.copy(point).addScaledVector(wallHit.face.normal.clone().transformDirection(wallHit.object.matrixWorld).normalize(), 0.12);
549:     state.face.lookAt(camera.position);
550:     state.face.rotation.y += Math.PI;
551:     state.face.rotation.z = Math.PI / 2;
552:     state.faceTimer = 1.8;
553:     state.faceCooldown = 8 + Math.random() * 10;
