557:   function shoot() {
558:     if (!state.gameOn || !state.player.gun || state.player.ammo <= 0) return;
559:     const now = performance.now();
560:     if (now - state.lastShot < 450) return;
561:     state.lastShot = now;
562:     state.player.ammo -= 1;
563:     updateUI();
564:     beep(220, 0.05, 0.02, 'square');
