566:     if (state.enemy && state.enemy.alive) {
567:       const dir = new T.Vector3(-Math.sin(state.player.yaw), Math.sin(state.player.pitch), -Math.cos(state.player.yaw));
568:       const enemyPos = new T.Vector3(state.enemy.x, 1.2, state.enemy.z);
569:       const dist = enemyPos.distanceTo(camera.position);
570:       const toEnemy = enemyPos.clone().sub(camera.position).normalize();
571:       if (dist < 12 && dir.dot(toEnemy) > 0.82) {
572:         state.enemy.hp -= 1;
573:         state.enemy.stun = 0.8;
574:         if (state.enemy.hp <= 0) {
575:           state.enemy.alive = false;
576:           state.enemy.group.visible = false;
577:           toast('La criatura cae.');
578:         } else {
579:           toast('Disparo certero.');
580:         }
581:       }
582:     }
583:   }
