585:   function tick(dt) {
586:     if (!state.gameOn) return;
587: 
588:     const moveX = (shiftPressed('KeyD') || shiftPressed('ArrowRight') ? 1 : 0) - (shiftPressed('KeyA') || shiftPressed('ArrowLeft') ? 1 : 0) + state.joy.x;
589:     const moveZ = (shiftPressed('KeyW') || shiftPressed('ArrowUp') ? 1 : 0) - (shiftPressed('KeyS') || shiftPressed('ArrowDown') ? 1 : 0) - state.joy.y;
590: 
591:     let dx = 0;
592:     let dz = 0;
593:     if (moveX || moveZ) {
594:       dx = -Math.sin(state.player.yaw) * moveZ + Math.cos(state.player.yaw) * moveX;
595:       dz = -Math.cos(state.player.yaw) * moveZ - Math.sin(state.player.yaw) * moveX;
596:       const m = Math.hypot(dx, dz);
597:       if (m > 0) {
598:         dx /= m; dz /= m;
599:       }
600:     }
601: 
602:     const s = (state.hold.Shift || state.running ? 4.7 : 2.6) * (state.crouching ? 0.55 : 1) * (state.hidden ? 0 : 1);
603:     const nx = state.player.x + dx * s * dt;
604:     const nz = state.player.z + dz * s * dt;
605:     if (canMove(nx, state.player.z)) state.player.x = nx;
606:     if (canMove(state.player.x, nz)) state.player.z = nz;
607: 
608:     state.player.food = Math.max(0, state.player.food - dt * 0.15);
609:     state.player.water = Math.max(0, state.player.water - dt * 0.2);
610:     if (state.player.food < 8 || state.player.water < 8) state.player.hp -= dt * 0.9;
611:     if (state.player.inf > 0) {
612:       state.player.inf = Math.max(0, state.player.inf - dt * 0.05);
613:       state.player.hp -= dt * 0.18 * state.player.inf * 0.05;
614:     }
615: 
616:     camera.position.set(state.player.x, state.crouching ? 1.12 : 1.62, state.player.z);
617:     camera.rotation.set(state.player.pitch, state.player.yaw, 0, 'YXZ');
618: 
619:     flashlightLight.visible = state.flashlight;
620:     flashlightLight.intensity = state.flashlight ? 26 : 0;
621:     flashlightLight.position.set(0, 0, 0);
622:     flashlightLight.target.position.set(0, 0, -1.4);
623:     flashlightLight.target.updateMatrixWorld();
624: 
625:     if (state.enemy && state.enemy.alive) {
626:       const ex = state.player.x - state.enemy.x;
627:       const ez = state.player.z - state.enemy.z;
628:       const dist = Math.hypot(ex, ez);
629:       if (dist > 0.6 && !state.hidden && state.enemy.stun <= 0) {
630:         const speed = 1.6;
631:         state.enemy.x += (ex / dist) * speed * dt;
632:         state.enemy.z += (ez / dist) * speed * dt;
633:       }
634:       state.enemy.stun = Math.max(0, state.enemy.stun - dt);
635:       state.enemy.group.position.set(state.enemy.x, 0, state.enemy.z);
636:       state.enemy.group.rotation.y = Math.atan2(state.player.x - state.enemy.x, state.player.z - state.enemy.z);
637:       if (dist < 1.3 && !state.hidden) {
638:         state.player.hp -= dt * 22;
639:         $('danger').style.opacity = '0.8';
640:       } else {
641:         $('danger').style.opacity = Math.max(0, Number($('danger').style.opacity || 0) - dt * 1.4) + '';
642:       }
643:     }
644: 
645:     if (state.face) {
646:       state.faceTimer -= dt;
647:       if (state.faceTimer <= 0) state.face.visible = false;
648:     }
649: 
650:     maybeFaces();
651: 
652:     const prompt = $('prompt');
653:     const target = nearestInteractable();
654:     if (target) {
655:       prompt.innerHTML = '<b>E</b>' + (target.type === 'hide' ? (state.hidden ? 'SALIR DEL ESCONDITE' : 'ESCONDERSE') : target.type === 'item' ? 'RECOGER · ' + target.label.toUpperCase() : 'ABRIR / USAR');
656:       prompt.classList.add('show');
657:       $('crosshair').classList.add('hot');
658:     } else {
659:       prompt.classList.remove('show');
660:       $('crosshair').classList.remove('hot');
661:     }
662: 
663:     if (state.player.hp <= 0) {
664:       finish(false);
665:       return;
666:     }
667: 
668:     if (performance.now() - state.uiTimer > 400) {
669:       updateUI();
670:       state.uiTimer = performance.now();
671:     }
672: 
673:     if (dx || dz) {
674:       if (performance.now() - state.lastFoot > 440) {
675:         state.lastFoot = performance.now();
676:         beep(70 + Math.random() * 20, 0.04, 0.012, 'triangle');
677:       }
678:     }
679:   }
