===================================================================
--- index.html
+++ index.html
@@ -8,9 +8,9 @@
 *{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#090a0a;color:var(--ink);font-family:Georgia,'Times New Roman',serif}button{font:inherit;color:inherit}
 .game{height:100dvh;display:grid;grid-template-rows:64px 1fr 66px;background:radial-gradient(ellipse at 50% 40%,#252421,#090a0a 70%)}
 header{display:flex;align-items:center;justify-content:space-between;padding:0 24px;border-bottom:1px solid #49443a;letter-spacing:.14em;text-transform:uppercase;background:#0d0e0d;z-index:6;position:relative}
 header .brand{display:flex;align-items:center;gap:12px;font-size:14px}header .sigil{color:var(--red);font-size:23px}header .chapter{font-size:11px;color:#b2a48b;letter-spacing:.2em}header .status{font:11px Arial,sans-serif;letter-spacing:.13em;color:#9e9689;display:flex;gap:14px;align-items:center}
-#audioBtn{cursor:pointer;border:1px solid #3f3a31;background:#151512;padding:4px 8px;color:#b9ad98;font:10px Arial,sans-serif;letter-spacing:.12em}#audioBtn:hover{border-color:#8a744f;color:#e8d6b4}
+#audioBtn,#settingsBtn{cursor:pointer;border:1px solid #3f3a31;background:#151512;padding:4px 8px;color:#b9ad98;font:10px Arial,sans-serif;letter-spacing:.12em}#audioBtn:hover,#settingsBtn:hover{border-color:#8a744f;color:#e8d6b4}
 .main{min-height:0;display:grid;grid-template-columns:minmax(0,1fr) 268px;gap:14px;padding:14px 18px}
 .scene-wrap{position:relative;min-width:0;overflow:hidden;border:1px solid #5b5141;box-shadow:0 0 45px #000;background:#0b0b0a}
 .scene-wrap:after{content:'';position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 30%,rgba(0,0,0,.7) 100%),linear-gradient(180deg,rgba(0,0,0,.15),transparent 22%,rgba(0,0,0,.35));z-index:2}
 canvas{width:100%;height:100%;display:block;outline:none;cursor:crosshair;touch-action:none}

input.newString:
.prompt.show{opacity:1}.prompt b{color:#e0b875;border:1px solid #8a714b;padding:1px 5px;margin-right:6px;font-weight:400}
 .settings{position:absolute;top:16px;right:16px;z-index:6;width:min(270px,calc(100% - 32px));padding:14px;background:#11110ff0;border:1px solid #746044;box-shadow:0 8px 26px #000b;font:11px Arial,sans-serif;letter-spacing:.08em;color:#d4c6ad;display:none}.settings.show{display:block}.settings label{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.settings input{width:100%;accent-color:#c13e35}.settings small{display:block;color:#8e8372;line-height:1.5;margin-top:8px}
 .danger.alarm{animation:alarmPulse .48s steps(2,end) infinite}
 @keyframes alarmPulse{0%,100%{opacity:.18;box-shadow:inset 0 0 80px 20px rgba(180,8,4,.65)}50%{opacity:.9;box-shadow:inset 0 0 180px 45px rgba(220,12,4,.98)}}

