383:   function nearestInteractable() {
384:     const forward = new T.Vector3(-Math.sin(state.player.yaw), 0, -Math.cos(state.player.yaw));
385:     let best = null;
386:     let bestD = 999;
387: 
388:     for (const it of state.interactables) {
389:       if (it.type === 'item' && it.collected) continue;
390:       const pos = it.pos;
391:       const dx = pos.x - state.player.x;
392:       const dz = pos.z - state.player.z;
393:       const d = Math.hypot(dx, dz);
394:       const to = new T.Vector3(dx, 0, dz).normalize();
395:       const dot = to.dot(forward);
396:       const reach = it.type === 'exit' ? 2.0 : 1.55;
397:       if (d <= reach && (d < 0.9 || dot > 0.72)) {
398:         if (d < bestD) { best = it; bestD = d; }
399:       }
400:     }
401:     return best;
402:   }
