  if (dist < 1.3 && !state.hidden) {
    state.player.hp -= dt * 22;
    $('danger').style.opacity = '0.8';
  } else {
    $('danger').style.opacity = Math.max(0, Number($('danger').style.opacity || 0) - dt * 1.4) + '';
  }
}

